import {MARKET, DIGITAL_COHORTS, DIGITAL_POTENTIAL, ECONOMIC_PROXY, marketScenario} from './src/market.js';
import {project, products, audiences, channels} from './src/brief.js';
import {formatPeople} from './src/universe.js';
import {simulate, EXAMPLE, restoreScenario} from './src/simulation.js';
import {guides, audienceSignals, productSignals} from './src/guides.js';
import {signalPlan} from './src/signals.js';
import {BUYER_EXAMPLE, restoreBuyerSplit, splitBuyerAudience, buyerExportRows} from './src/buyer-segments.js';
import {buyerPanel, buyerVisual} from './src/buyer-view.js';
const $=(q,root=document)=>root.querySelector(q);
const $$=(q,root=document)=>[...root.querySelectorAll(q)];
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(v);
const short=v=>new Intl.NumberFormat('es-CO',{maximumFractionDigits:2}).format(v/1e6)+' M';
const pct=v=>new Intl.NumberFormat('es-CO',{style:'percent',maximumFractionDigits:1}).format(v);
const icons={home:'<path d="m3 10 9-8 9 8v11h-6v-7H9v7H3Z"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M2 21v-3a7 7 0 0 1 14 0v3ZM17 4a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5v2"/>',box:'<path d="m3 6 9-4 9 4v12l-9 4-9-4ZM3 6l9 5 9-5M12 11v11M7 4l10 5"/>',chart:'<path d="M3 21V10h4v11M10 21V3h4v18M17 21V7h4v14"/>',sliders:'<path d="M2 5h20M2 12h20M2 19h20"/><circle cx="7" cy="5" r="2" fill="currentColor"/><circle cx="16" cy="12" r="2" fill="currentColor"/><circle cx="9" cy="19" r="2" fill="currentColor"/>',pin:'<path d="M19 9c0 5-7 13-7 13S5 14 5 9a7 7 0 0 1 14 0Z"/><circle cx="12" cy="9" r="2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>'};
function icon(id){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[id]||icons.info}</svg>`;}
$$('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
const routes=[['summary','Resumen','home'],['market','Universo','chart'],['audiences','Audiencias','users'],['products','Productos','box'],['media','Medios','chart'],['simulator','Simulador','sliders']];
$('#navigation').innerHTML=routes.map(([id,name,glyph])=>`<a href="#${id}" data-route="${id}">${icon(glyph)}<span>${name}</span></a>`).join('');
let marketState={qualification:35,price:80000,months:1,budgetShare:5};
let buyerState={...BUYER_EXAMPLE};
try{buyerState=restoreBuyerSplit(JSON.parse(localStorage.getItem('pads-buyers-v1')));}catch{}
let filter='all',query='',mapAudience='all',currentRoute='summary',lastFocus=null,guideContext={medium:'meta',audience:'productivas',product:'limpieza'},simState={...EXAMPLE},savedScenario=false;
try{const current=JSON.parse(localStorage.getItem('pads-scenario-v3')),legacy=JSON.parse(localStorage.getItem('pads-scenario-v2'));simState=restoreScenario(current,legacy);savedScenario=Boolean(current||legacy);localStorage.setItem('pads-scenario-v3',JSON.stringify(simState));}catch{}
function saveScenario(){try{localStorage.setItem('pads-scenario-v3',JSON.stringify(simState));savedScenario=true;return true;}catch{return false;}}

function buyerContext(scope=currentRoute){
 if(scope==='simulator'){const r=simulate(simState);return {universe:r.population.unique,currentShare:buyerState.currentShare,reach:r.final.unique,mode:'reach',id:'buyer-simulator'};}
 return {universe:MARKET.planningUniverse,currentShare:buyerState.currentShare,mode:'universe',id:'buyer-'+scope};
}
function buyerSection(scope){try{return buyerPanel(buyerContext(scope));}catch(error){return `<section class="panel buyer-panel"><p class="notice" role="alert">Corrige el escenario para ver el reparto por compradores: ${esc(error.message)}</p></section>`;}}
function refreshBuyerProjection(){const target=$('#buyer-sim-wrap');if(target)target.innerHTML=buyerSection('simulator');}
function changeBuyerShare(input){
 const value=input.value===''?NaN:Number(input.value),valid=Number.isFinite(value)&&value>=0&&value<=100;
 input.setAttribute('aria-invalid',String(!valid));input.setCustomValidity(valid?'':'Usa un porcentaje entre 0 y 100.');
 const error=$('[data-buyer-error]');if(error){error.hidden=valid;error.textContent=valid?'':'Usa un porcentaje entre 0 y 100. El gráfico conserva el último valor válido.';}
 if(!valid)return;
 buyerState={currentShare:value};try{localStorage.setItem('pads-buyers-v1',JSON.stringify(buyerState));}catch{}
 $$('[data-buyer-panel]').forEach(panel=>{
   const options={universe:Number(panel.dataset.buyerUniverse),reach:Number(panel.dataset.buyerReach),currentShare:value,mode:panel.dataset.buyerMode,id:panel.id};
   $('[data-buyer-visual]',panel).innerHTML=buyerVisual(options);
   $$('[data-buyer-share]',panel).forEach(control=>{if(control!==input)control.value=value;control.setAttribute('aria-invalid','false');control.setCustomValidity('');});
   $('[data-buyer-current-share]',panel).textContent=pct(value/100);$('[data-buyer-new-share]',panel).textContent=pct((100-value)/100);
 });
}
function showBuyerMethod(){openDialog(`<span class="eyebrow">Compradores actuales + audiencia nueva</span><h2 id="dialog-title">Cada persona, una sola vez.</h2><ul class="method-list"><li><strong>Compradores actuales:</strong> personas que ya compran pads de la categoría. No se limita a clientes de JGB ni implica que ya compren Control Poros.</li><li><strong>Nueva audiencia:</strong> el resto del universo propuesto para incorporar a la categoría, excluyendo al grupo de compradores actuales. Por definición, la intersección entre estos dos grupos es cero.</li><li><strong>Ejemplo inicial:</strong> 20% actuales y 80% nueva audiencia. Es un supuesto editable para explorar; no proviene de DANE, de un estudio de penetración, de CRM ni de resultados de medios. El porcentaje activo es ${pct(buyerState.currentShare/100)}.</li><li><strong>Universo:</strong> compradores supuestos = universo × porcentaje; nueva audiencia = universo − compradores supuestos. Redondeamos las personas de la base y conservamos el total exacto. El universo nacional sigue siendo 30 M para comunicación.</li><li><strong>Alcance del simulador:</strong> se toma el alcance único del modelo por producto y se reparte según la composición de la base, suponiendo la misma tasa de exposición para ambos perfiles. Cambiar el porcentaje no aumenta el alcance total, no modifica presupuesto ni CPM y no predice ventas. El gasto se sigue distribuyendo por producto; esta vista no es un presupuesto independiente por perfil.</li><li><strong>Cómo validar:</strong> usar un estudio de categoría con definición y período de compra claros, o datos representativos de compra. Un CRM de JGB identifica compradores registrados de la marca; no mide todos los compradores de pads. La ausencia de un registro tampoco demuestra que una persona nunca haya comprado la categoría.</li><li><strong>Lectura del dibujo:</strong> los círculos están separados porque los grupos se excluyen. Sus áreas son esquemáticas. El cruce entre líneas de producto del simulador sigue siendo otro concepto: una persona puede recibir publicidad de ambas líneas y pertenecer a un solo perfil de compra.</li></ul><p class="notice">El análisis de disposición a pagar $80.000 continúa por separado. El público nuevo alcanzado no equivale a nuevos compradores obtenidos.</p>`);}
function exportBuyers(){try{const c=buyerContext();download('PADS_Compradores_y_Nueva_Audiencia.csv',csv([['PADS · Reparto por relación con la categoría'],['Vista',c.mode==='reach'?'Alcance proyectado · 12 olas':'Universo de planeación'],['Cobertura','Toda Colombia'],['Edad','18+ sin límite superior'],['Género','Todos los géneros'],...buyerExportRows(c.universe,c.currentShare,c.mode==='reach'?c.reach:undefined)]),'text/csv;charset=utf-8');toast('Reparto exportado con sus supuestos.');}catch(error){toast(error.message);}}

const mark=id=>`<span class="channel-mark ${id}" aria-hidden="true">${id==='ctv'?'<svg viewBox="0 0 32 32"><rect x="3" y="5" width="26" height="19" rx="3"/><path d="M11 28h10M16 24v4"/></svg>':`<img src="assets/media/${id}.svg" alt="">`}</span>`;
const filterName=()=>filter==='all'?'Todo el portafolio':products.find(p=>p.id===filter).name;
function pills(){return `<div class="pills" role="group" aria-label="Filtrar por producto">${[['all','Todo el portafolio'],['limpieza','Limpieza'],['control-poros','Control Poros']].map(([id,n])=>`<button class="pill ${filter===id?'active':''}" data-action="filter" data-value="${id}" aria-pressed="${filter===id}">${n}</button>`).join('')}</div>`;}
const round='<span class="round-arrow" aria-hidden="true">›</span>';
const contextNote=()=>`<p class="notice">${filter==='all'?'Los cinco grupos son perfiles de planeación que pueden cruzarse.':'Vista de '+esc(filterName())+'. Los perfiles describen oportunidades de comunicación para esta línea.'} No representan audiencias medidas ni grupos de personas mutuamente excluyentes.</p>`;
function intro(kicker,title,description,action=''){return `<div class="page-intro"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function productTile(p){return `<button class="product-tile ${p.id==='control-poros'?'sage':''}" data-action="product" data-value="${p.id}"><div class="mini-stage"><img src="${p.assets[0]}" alt="Empaque de ${p.name}">${p.assets[1]?`<img class="second-pack" src="${p.assets[1]}" alt="Pads cuadrados">`:''}</div><div><span class="eyebrow">${p.step} · ${p.role}</span><h2>${p.id==='limpieza'?'Pads':'Control Poros'}</h2><p>${p.id==='limpieza'?'Limpieza cotidiana':'Cuidado específico'}</p></div>${round}</button>`;}
function audienceCard(a,detailed=false){const idx=audiences.indexOf(a);return `<button class="audience-card" data-action="audience" data-value="${a.id}" aria-label="Ver audiencia ${a.name}"><div class="portrait" style="--portrait:${idx}" role="img" aria-label="Retrato ilustrativo de ${a.name}"></div>${detailed?`<div class="audience-body"><span class="eyebrow">${String(idx+1).padStart(2,'0')} · Audiencia</span><h3>${a.name}</h3><p>${a.context}</p><span class="tag">${a.need}</span><div class="text-link">Explorar perfil ${icon('arrow')}</div></div>`:`<div class="audience-caption">${a.name}${round}</div>`}</button>`;}
function summary(){return `<section class="skin-hero" aria-labelledby="hero-title"><div class="skin-copy"><span class="eyebrow">JGB · Dos pasos para tu cuidado</span><h1 id="hero-title">El cuidado empieza<br>por conocerte.</h1><p>Dos productos. Dos momentos.<br>Una rutina que conecta con su día a día.</p><div class="skin-universe"><span class="skin-universe-icon">${icon('users')}</span><div><strong>30 millones</strong><span>Universo de comunicación · Toda Colombia · 18+</span><small>Todos los géneros · análisis de compra a $80.000 por separado</small><a class="text-link" href="#market">Ver cómo dimensionamos el mercado ›</a></div></div></div><div class="skin-products" aria-label="Portafolio Pads JGB"><figure class="skin-pack skin-pack-clean"><div class="skin-pack-image"><img src="assets/pads-redondos.png" alt="Empaque completo de Pads JGB de algodón"></div><figcaption><span>01 · LIMPIAR</span><strong>Pads de algodón</strong></figcaption></figure><figure class="skin-pack skin-pack-pore"><div class="skin-pack-image"><img src="assets/pads-control-poros.png" alt="Empaque completo de Pads JGB Control Poros"></div><figcaption><span>02 · TRATAR</span><strong>Control Poros</strong></figcaption></figure></div></section>
<section class="panel product-panel" aria-label="Productos"><div class="filter-row"><span class="filter-label">Explorar productos:</span>${pills()}</div><div class="product-grid">${products.filter(p=>filter==='all'||p.id===filter).map(productTile).join('')}</div></section>
<section class="panel" aria-labelledby="audience-heading"><div class="section-heading"><h2 id="audience-heading">Cinco formas de vivir el cuidado</h2><a href="#map" class="text-link">${icon('pin')} Explorar Colombia ›</a></div><div class="audience-grid">${audiences.map(a=>audienceCard(a)).join('')}</div></section>
<section class="panel media-strip" aria-label="Activación por medios"><div><h2>Activación por medios</h2><p>Conecta con sus momentos en los canales que hacen parte de su vida.</p></div><div class="channel-links">${channels.map(c=>`<button class="channel-link" data-action="guide" data-value="${c.id}">${mark(c.id)}${c.name==='CTV'?'CTV':c.name}</button>`).join('')}</div><a href="#media" class="button">Ver guía de segmentación ›</a></section>`;}
function audienceView(){return `${intro('Personas · necesidades · momentos','El cuidado no tiene un solo perfil.','Toda Colombia, desde los 18 años, sin límite superior y todos los géneros. Cinco contextos que se cruzan; sin restricciones por ciudad.',`<button class="button" data-action="export-audiences">Exportar audiencias ↓</button>`)}${buyerSection('audiences')}<section class="panel"><div class="toolbar">${pills()}<input class="search" id="audience-search" type="search" placeholder="Buscar necesidad o audiencia…" aria-label="Buscar audiencias" value="${esc(query)}"></div><div class="audience-grid detailed" id="audience-results">${audienceResults()}</div>${contextNote()}<div class="signal-preview"><h3>Señales que se pueden convertir en un plan</h3><p>Abre un perfil para explorar contextos, búsquedas y mensajes. Elige un medio para ver dónde activarlos, qué comparar y cómo medir la prueba.</p><div class="inline-actions">${channels.map(c=>`<button class="button" data-action="guide" data-value="${c.id}">${mark(c.id)} ${c.name} ›</button>`).join('')}</div></div><p class="small muted" style="margin-top:10px">Retratos ilustrativos generados con IA. Tamaños por grupo pendientes de definición.</p></section>`;}
function audienceResults(){const normalize=t=>t.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const results=audiences.filter(a=>normalize([a.name,a.context,a.need,a.message].join(' ')).includes(normalize(query)));return results.length?results.map(a=>audienceCard(a,true)).join(''):'<p class="empty">No encontramos coincidencias. Prueba con “rutina”, “viaje” o “madres”.</p>';}
function productsView(){return `${intro('Un portafolio · dos funciones','Primero limpias. Después tratas.','Dos pasos complementarios, con un propósito claro dentro de la rutina.')}<section class="panel"><div class="product-detail-grid">${products.map(p=>`<article class="product-detail ${p.id==='control-poros'?'sage':''}"><img src="${p.assets[0]}" alt="${p.name}"><span class="eyebrow">${p.step} · ${p.role}</span><h2>${p.name}</h2><p>${p.description}</p><p class="serif" style="font-size:22px;color:var(--ink)">${p.territory}</p><button class="button" data-action="product" data-value="${p.id}">Explorar este producto ›</button></article>`).join('')}</div><div class="table-wrap"><table class="compare-table"><caption class="small muted" style="text-align:left;margin-top:25px">Cómo conviven en el portafolio · síntesis del brief</caption><thead><tr><th scope="col">En la rutina</th><th scope="col">Pads</th><th scope="col">Control Poros</th></tr></thead><tbody><tr><th scope="row">Rol</th><td>Limpieza y desmaquillado</td><td>Cuidado específico de los poros</td></tr><tr><th scope="row">Momento</th><td>Paso de limpieza</td><td>Después de limpiar</td></tr><tr><th scope="row">Conversación</th><td>Suavidad y practicidad</td><td>Entender el nuevo paso</td></tr><tr><th scope="row">Creatividad</th><td>Demostrar el uso en la rutina</td><td>Explicar las diferencias del producto</td></tr></tbody></table></div><div class="notice">El universo es compartido: una persona puede considerar las dos líneas. El reparto por producto se define en el simulador; no se deduce del formato del empaque.</div></section>`;}
function mediaView(){return `${intro('Del insight a la activación','Cada medio tiene su momento.','Explora cómo llevar las hipótesis de audiencia a una prueba de medios. Las guías incluyen ejemplos y fuentes.')}<section class="panel"><div class="filter-row"><span class="filter-label">Contexto de producto:</span>${pills()}</div><div class="medium-grid">${channels.map(c=>`<article class="medium-card">${mark(c.id)}<h2>${c.name}</h2><p>${c.role}</p><span class="tag">${c.format}</span><small>${c.id==='ctv'?'Proveedor e inventario por definir':c.id==='meta'?'Configuración por validar en cuenta':'Guía con documentación oficial'}</small><button class="button" data-action="guide" data-value="${c.id}">Cómo segmentar en ${c.name} ›</button></article>`).join('')}</div><p class="notice">No hay cuentas publicitarias conectadas. Los ejemplos son hipótesis para probar, no intereses garantizados, resultados históricos ni estimaciones de la plataforma. Pinterest y CTV requieren validar disponibilidad comercial.</p></section>`;}
function mapView(){const a=audiences.find(a=>a.id===mapAudience);return `${intro('Colombia · 18+ · todos los géneros','El cuidado, en todo el país.','Explora hábitos y necesidades nacionales. Los clústeres no dependen de ciudades ni tienen tamaños asignados.')}<section class="panel"><div class="map-layout national-map-layout"><div class="city-list" role="group" aria-label="Explorar clústeres nacionales"><button class="city-button ${!a?'active':''}" data-action="map-audience" data-value="all" aria-pressed="${!a}">Todos los clústeres <span>›</span></button>${audiences.map(c=>`<button class="city-button ${c.id===mapAudience?'active':''}" data-action="map-audience" data-value="${c.id}" aria-pressed="${c.id===mapAudience}">${c.name}<span>›</span></button>`).join('')}</div><div class="map-stage national-map-stage"><img src="assets/colombia.svg" alt="Contorno de Colombia continental, referencia visual de cobertura nacional"><div class="national-map-badge"><strong>Colombia</strong><span>18+ · sin límite superior</span></div></div><article class="city-panel" aria-live="polite"><span class="eyebrow">Afinidad nacional · todos los géneros</span><h2>${a?a.name:'Un país. Muchas rutinas.'}</h2><p>${a?a.context:'Personas de zonas urbanas y rurales que pueden descubrir los dos pasos del portafolio.'}</p><span class="tag">Limpieza</span><span class="tag">Control Poros</span><p><strong>${a?'Necesidad para explorar':'Base nacional compartida'}</strong><br>${a?a.need:'30 M de personas para planear comunicación. El tamaño de cada clúster está por validar.'}</p>${a?`<button class="button" data-action="audience" data-value="${a.id}">Ver señales y medios ›</button>`:'<a href="#audiences" class="button">Explorar todos los perfiles ›</a>'}</article></div><p class="notice">Cobertura de planeación: todo el territorio colombiano, incluido el insular. El contorno continental es una referencia visual. Las afinidades no excluyen ciudades; la distribución comercial y el inventario publicitario se validan al activar.</p></section>`;}

function input(name,label,extra=''){return `<label class="field-label">${label}<input type="number" id="${name}" name="${name}" data-sim="${name}" value="${simState[name]}" min="0" ${extra}></label>`;}
function simulatorView(){return `${intro('Escenarios · alcance · frecuencia','Un universo. Sin contar dos veces.','Ajusta el reparto entre líneas y explora una curva de alcance. Base inicial de comunicación: 30 M de adultos en toda Colombia. El alcance responde al presupuesto; no representa compradores ni inversión aprobada.',`<button class="button" data-action="export-sim">Exportar escenario ↓</button>`)}<div id="buyer-sim-wrap">${buyerSection('simulator')}</div><section class="panel simulation-layout"><div class="sim-controls"><div class="control-group"><h3>01 · Reparto de personas</h3><p class="small muted">Tres grupos exclusivos de planeación. La base inicial de 30 M es compartida por ambas líneas para comunicación; no supone que compren o prefieran los dos productos. Puedes editar el reparto.</p>${input('cleansingOnly','Solo limpieza','step="100000" max="39721750"')}${input('shared','Ambas líneas','step="100000" max="39721750"')}${input('poreCareOnly','Solo Control Poros','step="100000" max="39721750"')}</div><div class="control-group"><h3>02 · Hipótesis de inversión</h3>${input('budget','Inversión total · COP','step="1000000" max="1000000000000"')}${input('cpm','CPM supuesto · COP','step="100"')}<label class="field-label" for="cleansingShare">Mezcla de inversión <strong id="share-value">${simState.cleansingShare}% limpieza</strong></label><input id="cleansingShare" type="range" min="0" max="100" step="1" value="${simState.cleansingShare}" data-sim="cleansingShare"><div class="range-labels"><span>0% Limpieza</span><span>100% Limpieza</span></div><button class="text-link" data-action="reset-sim">Restablecer base de 30 M ↺</button></div><p class="notice" id="save-status">${savedScenario?'Escenario recuperado de este navegador.':'Base nacional de comunicación. Edita inversión y reparto para construir tu escenario.'} Solo los escenarios válidos se guardan en este navegador.</p></div><div class="sim-results" id="sim-results" aria-live="polite">${simResults()}</div></section>`;}
function simResults(){try{const result=simulate(simState), f=result.final,p=result.population;return `<div class="scenario-scope"><strong>${short(p.unique)}</strong><span>Universo activo de planeación<br>Toda Colombia · 18+ · todos los géneros</span></div><div class="sim-kpis"><div class="metric"><span>Alcance único estimado</span><strong>${short(f.unique)}</strong><small>${pct(f.coverage)} del universo</small></div><div class="metric"><span>Frecuencia media</span><strong>${f.frequency.toLocaleString('es-CO',{maximumFractionDigits:1})}</strong><small>Impresiones / personas únicas</small></div><div class="metric"><span>Inversión del escenario</span><strong>${short(simState.budget)}</strong><small>COP · ${money(simState.cpm)} CPM supuesto</small></div></div><h3>Composición del universo</h3><div class="allocation-bar" aria-label="Distribución exclusiva del universo"><span style="width:${p.cleansingOnly/p.unique*100}%;background:#bea3cc"></span><span style="width:${p.shared/p.unique*100}%;background:#7c528f"></span><span style="width:${p.poreCareOnly/p.unique*100}%;background:#a8c3b0"></span></div><div class="allocation-labels"><span>Solo limpieza<br><strong>${short(p.cleansingOnly)}</strong></span><span>Ambas líneas<br><strong>${short(p.shared)}</strong></span><span>Solo Control Poros<br><strong>${short(p.poreCareOnly)}</strong></span></div><h3>Alcance acumulado · 12 olas iguales</h3>${reachChart(result.rows,p.unique)}<div class="chart-caption"><span><i class="legend-dot"></i>Únicos combinados</span><span><i class="legend-dot clean"></i>Limpieza</span><span><i class="legend-dot pore"></i>Control Poros</span></div><p class="sim-explanation">Audiencia potencial por línea: <strong>${short(p.cleansing)}</strong> limpieza y <strong>${short(p.poreCare)}</strong> Control Poros. Comparten <strong>${short(p.shared)}</strong>; el total único del escenario es <strong>${short(p.unique)}</strong>. Al cierre, el modelo descuenta ${short(f.overlap)} personas alcanzadas por ambas líneas.</p><details class="disclosure"><summary>Ver las 12 olas y las fórmulas</summary><div class="table-wrap"><table class="compare-table sim-table"><thead><tr><th>Ola</th><th>Inversión acumulada</th><th>Únicos</th><th>Frecuencia</th></tr></thead><tbody>${result.rows.map(r=>`<tr><td>${r.period}</td><td>${money(r.spend)}</td><td>${formatPeople(Math.round(r.unique))}</td><td>${r.frequency.toFixed(2)}</td></tr>`).join('')}</tbody></table></div><p class="sim-explanation">Impresiones = inversión / CPM × 1.000. Alcance de cada línea = audiencia × (1 − exp(−impresiones / audiencia)). Intersección alcanzada = grupo compartido × tasa de alcance de limpieza × tasa de alcance de Control Poros. Únicos = alcance de ambas líneas menos intersección. Supone exposición homogénea, independencia entre líneas dentro del grupo compartido y distribución uniforme de inversión en 12 olas. No incluye diferencias de CPM por medio ni datos de campaña.</p></details><p class="notice">Modelo ilustrativo de saturación. El CPM, el presupuesto y el reparto son hipótesis editables. El resultado no equivale al pronóstico de una plataforma ni a alcance garantizado.</p>`;}catch(e){return `<div class="sim-error" role="alert"><strong>Revisa el escenario</strong><p>${esc(e.message)}</p><p class="small" style="margin-top:12px">La última versión válida se conserva. Corrige los campos para volver a calcular.</p></div>`;}}
function reachChart(rows,total){const x=i=>48+i*42.2,y=v=>244-v/total*204;const path=k=>[{[k]:0},...rows].map((r,i)=>`${i?'L':'M'}${x(i)},${y(r[k])}`).join(' ');return `<svg class="chart" viewBox="0 0 590 285" role="img" aria-label="Curvas de alcance estimado acumulado para doce olas"><title>Alcance de limpieza, Control Poros y únicos combinados</title>${[0,total*.25,total*.5,total*.75,total].map(v=>`<line x1="48" x2="560" y1="${y(v)}" y2="${y(v)}" stroke="#e7deec" stroke-dasharray="3 5"/><text x="8" y="${y(v)+4}">${short(v)}</text>`).join('')}<path d="${path('unique')} L${x(12)},244 L48,244Z" fill="#e9ddef" opacity=".55"/>${[['cleanReach','#b79bc5'],['poreReach','#84a58f'],['unique','#835597']].map(([k,color])=>`<path d="${path(k)}" fill="none" stroke="${color}" stroke-width="${k==='unique'?3:2}" stroke-linecap="round"/>`).join('')}${[0,2,4,6,8,10,12].map(i=>`<text x="${x(i)}" y="270" text-anchor="middle">${i===0?'Inicio':'Ola '+i}</text>`).join('')}</svg>`;}
function marketSources(){return `<div class="sources"><a href="${MARKET.populationUrl}" target="_blank" rel="noopener noreferrer">DANE · Población por edad · julio 2025 ↗</a><a href="${MARKET.internetUrl}" target="_blank" rel="noopener noreferrer">DANE · Uso de internet 2025 · septiembre 2026 ↗</a><a href="${MARKET.incomeUrl}" target="_blank" rel="noopener noreferrer">DANE · Clases sociales 2025 · agosto 2026 ↗</a></div>`;}
function nationalMarketPanel(){return `<section class="market-national panel" aria-label="Universo nacional de comunicación"><div class="market-national-main"><span class="eyebrow">Base recomendada de planeación · 2027</span><strong class="market-national-number">30<span>millones</span></strong><h2>Una base amplia para dar a conocer PADS.</h2><p>Adultos de toda Colombia, hombres y mujeres. Limpieza y Control Poros comparten esta base de comunicación.</p><div class="scope-tags"><span>18+ sin límite superior</span><span>Todos los géneros</span><span>Urbano y rural</span></div><button class="button primary" data-action="apply-national">Usar 30 M en el simulador ${icon('arrow')}</button><small>Universo potencial de comunicación. El alcance depende de la inversión y el CPM; no es una cifra de compradores.</small></div><div class="market-basis"><article><span>01 · Marco demográfico</span><strong>${short(MARKET.adults)}</strong><h3>Adultos en Colombia · 2027</h3><p>Proyección DANE, suma de todas las edades desde 18 hasta 100 y más.</p></article><article><span>02 · Potencial digital</span><strong>${short(DIGITAL_POTENTIAL)}</strong><h3>Estimación propia</h3><p>Población 2027 × tasas de internet 2025 por edad, mantenidas constantes.</p></article><p class="market-margin">Los 30 M equivalen al ${pct(MARKET.planningUniverse/DIGITAL_POTENTIAL)} del potencial digital calculado. El margen restante es una decisión de planeación, no inventario publicitario medido.</p></div></section><section class="panel market-evidence"><details><summary>Ver cálculo, supuestos y fuentes del universo</summary><p>La base no se reduce por ciudades, género o clúster. Los perfiles guían mensajes y señales; no prueban afinidad ni compra. Tampoco sumamos audiencias de plataformas como si fueran personas diferentes.</p><div class="table-wrap"><table class="compare-table"><thead><tr><th>Edad</th><th>Población 2027</th><th>Internet 2025</th><th>Digital estimado</th></tr></thead><tbody>${DIGITAL_COHORTS.map(c=>`<tr><th scope="row">${c.age}</th><td>${formatPeople(c.population)}</td><td>${pct(c.internetRate)}${c.age==='18–24'?'*':''}</td><td>${formatPeople(Math.round(c.population*c.internetRate))}</td></tr>`).join('')}</tbody></table></div><p class="notice">* Para 18–24 usamos la tasa publicada de 12–24 como aproximación. Mantener las tasas de 2025 hasta 2027 no incorpora cambios de uso; este cálculo no es una proyección oficial de usuarios de internet del DANE. Los 30 M no miden compradores ni disponibilidad certificada en una plataforma.</p>${marketSources()}</details></section>`;}
function marketView(){return `${intro('Colombia · 18+ · planeación 2027','Más personas. Una base nacional.','Ampliamos el universo de comunicación a 30 millones. La posible compra a $80.000 se analiza por separado, con hipótesis visibles.',`<button class="button" data-action="export-market">Exportar análisis ↓</button>`)}${nationalMarketPanel()}${buyerSection('market')}<section class="panel"><div class="section-heading"><h2>¿Y cuántas personas podrían comprarlo?</h2><span class="tag">Análisis de precio · $80.000</span></div><div class="economic-reference"><strong>${short(ECONOMIC_PROXY)}</strong><div><b>Referencia económica aproximada · cálculo propio</b><p>${short(MARKET.adults)} adultos de 2027 × 41,3% de clase media y alta observado en 2025 para todas las edades. Supone igual proporción por edad y estabilidad entre años. No mide compradores ni cruza ingresos con uso de internet; tampoco excluye compras ocasionales fuera de esos grupos.</p></div></div><p class="small muted">Referencia para el producto de $80.000: SKU por confirmar. El precio del algodón se debe dimensionar aparte. La recompra no es una indicación de frecuencia de uso.</p><div class="market-controls"><label class="field-label">Precio por unidad · COP<input type="number" min="1" step="1000" data-market="price" value="${marketState.price}"></label><label class="field-label">Meses entre compras<input type="number" min="1" max="24" step="1" data-market="months" value="${marketState.months}"></label><label class="field-label">Presupuesto para este producto · % del ingreso mensual por persona<input type="number" min="0.1" max="100" step="0.5" data-market="budgetShare" value="${marketState.budgetShare}"></label><label class="field-label">Afinidad + acceso + disposición al precio · % conjunto supuesto<input type="number" min="0" max="100" step="1" data-market="qualification" value="${marketState.qualification}"></label></div><div id="market-results" aria-live="polite">${marketResults()}</div></section><section class="panel"><h2>Qué falta para hablar de compradores</h2><div class="signal-grid"><div class="signal-block"><h3>1 · Precisar la oferta</h3><p>Confirmar SKU, contenido del empaque, precio efectivo y duración. Separar algodón de Control Poros; no comparten necesariamente precio ni frecuencia de compra.</p></div><div class="signal-block"><h3>2 · Medir interés al precio real</h3><p>Encuesta con hombres y mujeres adultos, cuotas por edad e ingreso, uso actual de la categoría y disposición a pagar. Preguntar por $80.000 explícitamente, sin convertir interés general en compra.</p></div><div class="signal-block"><h3>3 · Confirmar acceso y respuesta</h3><p>Cobertura de distribución y disponibilidad; prueba de medios con ficha de producto, precio visible y eventos de intención o compra cuando estén disponibles.</p></div><div class="signal-block"><h3>4 · Dimensionar el mercado final</h3><p>Cruzar edad e ingreso en microdatos y aplicar tasas observadas de afinidad, acceso y disposición. Estimar compradores en un período definido, con incertidumbre explícita.</p></div></div><a class="button" href="#audiences">Explorar contextos de hombres y mujeres ›</a></section>`;}
function marketResults(){try{const r=marketScenario(marketState);return `<div class="market-kpis"><div class="metric"><span>Costo mensual equivalente</span><strong>${money(r.monthlyCost)}</strong><small>Precio / meses entre compras</small></div><div class="metric"><span>Ingreso mensual por persona requerido*</span><strong>${money(r.threshold)}</strong><small>Con presupuesto del ${marketState.budgetShare}% para este producto</small></div><div class="metric"><span>Escenario condicionado · sin medición</span><strong>${short(r.qualified)}</strong><small>${short(ECONOMIC_PROXY)} × ${marketState.qualification}% supuesto conjunto</small></div></div><p class="notice">*Es un umbral aritmético de presupuesto, no una regla de asequibilidad ni ingreso disponible. En el umbral inferior de clase media de 2025 ($943.791 por persona/mes), el costo mensual equivale a ${pct(r.burden)} del ingreso. No contamos cuántas personas superan el umbral calculado porque falta el cruce de ingresos. Cambiar precio o recompra modifica este diagnóstico; no inventa una respuesta de demanda.</p><div class="table-wrap"><table class="compare-table"><caption>Sensibilidad exploratoria · no pronóstico de ventas ni intervalo estadístico</caption><thead><tr><th>Supuesto conjunto</th><th>Público condicionado</th><th>Lectura</th></tr></thead><tbody>${[20,35,50].map(q=>`<tr><td>${q}% de la referencia económica</td><td>${short(Math.round(ECONOMIC_PROXY*q/100))}</td><td>Si esa proporción combina afinidad, acceso y disposición al precio</td></tr>`).join('')}</tbody></table></div><p class="notice"><strong>No existe todavía una cifra validada de compradores.</strong> El rango cambia porque cambiamos un supuesto sin medición. No representa alcance digital ni ventas; el porcentaje conjunto debe reemplazarse por evidencia.</p><button class="button" data-action="apply-market">Simular esta hipótesis de ${short(r.qualified)} ›</button><p class="small muted">Se coloca solo en la línea Control Poros, como hipótesis de trabajo para el producto de $80.000; confirmar SKU. No asigna audiencia al algodón ni solapamiento. Puedes editar el reparto después.</p>`;}catch(e){return `<p class="notice" role="alert">${esc(e.message)}</p>`;}}
function render(){const next=location.hash.slice(1).split('?')[0]||'summary';currentRoute=[...routes.map(r=>r[0]),'map'].includes(next)?next:'summary';const views={summary,market:marketView,audiences:audienceView,products:productsView,media:mediaView,map:mapView,simulator:simulatorView};$('#content').innerHTML=views[currentRoute]();$$('[data-route]').forEach(a=>{const active=a.dataset.route===currentRoute;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.title=`${routes.find(r=>r[0]===currentRoute)?.[1]||'Colombia'} · PADS Audience Lab`;$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}
function openDialog(html){lastFocus=document.activeElement;$('#dialog-content').innerHTML=html;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();}
function closeDialog(){$('#detail-dialog').close();if(lastFocus?.isConnected)lastFocus.focus();}
function audienceDetail(id){const a=audiences.find(a=>a.id===id);if(!a)return;const p=filter==='all'?'limpieza':filter;openDialog(`<div class="profile-head"><div class="portrait" style="--portrait:${audiences.indexOf(a)}" role="img" aria-label="Retrato ilustrativo"></div><div><span class="eyebrow">Audiencia · ${filterName()}</span><h2 id="dialog-title">${a.name}</h2><p>${a.context}</p><span class="tag">${a.need}</span><p class="small muted">Toda Colombia · 18+ sin límite superior · todos los géneros</p></div></div><p class="quote">“${a.message}”</p><h3>Una conversación para cada paso</h3><p><strong>Limpieza:</strong> mostrar limpieza facial para hombres y mujeres; desmaquillado cuando corresponda.</p><p><strong>Control Poros:</strong> explicar qué aporta este nuevo paso y cómo se diferencia de limpiar.</p>${signalMarkup(id,p)}<h3>Llevar esta audiencia a medios</h3><div class="inline-actions">${channels.map(c=>`<button class="button" data-action="audience-guide" data-audience="${id}" data-value="${c.id}">${c.name} ›</button>`).join('')}</div><p class="notice">Perfil editorial ampliado a hombres y mujeres; toma como punto de partida los momentos del brief, páginas ${a.briefPages.join(', ')}. Retrato ilustrativo generado con IA. Sin tamaño asignado.</p>`);}
function productDetail(id){const p=products.find(p=>p.id===id);if(!p)return;openDialog(`<span class="eyebrow">${p.step} · ${p.role}</span><h2 id="dialog-title">${p.name}</h2><div class="product-detail ${id==='control-poros'?'sage':''}" style="margin-top:20px"><img src="${p.assets[0]}" alt="${p.name}"><p class="quote" style="background:none;padding:0">${p.territory}</p><p>${p.description}</p><p>${id==='limpieza'?'El brief presenta formatos de algodón redondos y cuadrados para la limpieza.':'El brief presenta una fórmula con AHA, BHA y centella y una doble textura. Los detalles de uso deben corresponder al etiquetado aprobado.'}</p></div><h3>Cómo comunicarlo</h3><p>${id==='limpieza'?'Hablar de suavidad, practicidad y ese momento de quitarse el día de encima. Mostrar el producto dentro del paso de limpieza.':'Educar sobre la diferencia entre limpiar y tratar. Demostrar el lugar de Control Poros en la rutina sin prometer resultados clínicos no documentados.'}</p><div class="dialog-actions"><button class="button primary" data-action="product-audiences" data-value="${id}">Ver sus audiencias ›</button><button class="button" data-action="product-media" data-value="${id}">Activación por medios ›</button></div><p class="notice">Fuente: brief JGB, páginas ${p.briefPages.join(', ')}. Los empaques se conservan del documento suministrado.</p>`);}
function signalMarkup(audience,product,medium){const s=signalPlan(audience,product,medium||'meta');return `<div class="signal-intro"><span class="eyebrow">${medium?'Plan de activación':'Mapa de señales'} · ${product==='limpieza'?'Limpieza':'Control Poros'}</span><h3>Del momento a la señal.</h3><p class="small muted">Toda Colombia · 18+ sin límite superior · todos los géneros</p><p>${esc(s.moment)}</p></div><div class="signal-grid"><section class="signal-block"><h3>01 · Contextos para explorar</h3>${s.contexts.map(v=>`<span class="tag">${esc(v)}</span>`).join('')}<p>Territorios de contenido; no prueban que una persona pertenezca al perfil.</p></section><section class="signal-block"><h3>02 · Interés en el producto</h3>${s.topics.map(v=>`<span class="tag">${esc(v)}</span>`).join('')}<p>Familias temáticas para validar en el medio elegido.</p></section><section class="signal-block"><h3>03 · Búsquedas propuestas</h3><ul>${s.searches.map(v=>`<li>${esc(v)}</li>`).join('')}</ul><p>Sin volumen medido. Su uso depende del medio.</p></section><section class="signal-block"><h3>04 · Pieza y mensaje</h3><p><strong>${esc(s.creative)}</strong></p><p>${esc(s.productMessage)}</p></section>${medium?`<section class="signal-block wide"><span class="eyebrow">Dónde y cómo activarlo</span><h3>${esc(s.place)}</h3><p>${esc(s.input)}</p></section><section class="signal-block"><h3>05 · Datos propios</h3><p>${esc(s.remarketing)}</p></section><section class="signal-block"><h3>06 · Prueba y medición</h3><p>${esc(s.test)}</p><p><strong>Leer resultados:</strong> ${esc(s.metric)}</p></section>`:''}</div><p class="small muted">Hipótesis de planeación. ${esc(s.validation)}</p>`;}
function guideDetail(id,audience=guideContext.audience){guideContext={medium:id,audience,product:filter==='all'?guideContext.product:filter};renderGuide();}
function renderGuide(){const {medium,audience,product}=guideContext;const g=guides[medium];const a=audiences.find(a=>a.id===audience);if(!g)return;const examples=[...audienceSignals[audience],...productSignals[product]];openDialog(`<span class="eyebrow">Activación por medios</span>${mark(medium)}<h2 id="dialog-title">Cómo segmentar en ${g.title}</h2><p>${g.status}</p><div class="guide-context"><label class="field-label">Audiencia<select id="guide-audience">${audiences.map(a=>`<option value="${a.id}" ${a.id===audience?'selected':''}>${a.name}</option>`).join('')}</select></label><label class="field-label">Producto<select id="guide-product">${products.map(p=>`<option value="${p.id}" ${p.id===product?'selected':''}>${p.name}</option>`).join('')}</select></label></div><ol class="steps">${g.steps.map(s=>`<li><span>${s}</span></li>`).join('')}</ol>${signalMarkup(audience,product,medium)}<p class="notice">${g.note}</p><div class="sources">${g.sources.map(([name,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${name} ↗</a>`).join('')}</div><div class="dialog-actions"><button class="button primary" data-action="copy-guide">Copiar guía y ejemplos</button><button class="button secondary" data-action="download-guide">Descargar guía</button></div>`);}
function method(){openDialog(`<span class="eyebrow">Fuentes y supuestos</span><h2 id="dialog-title">Un mercado que debemos dimensionar.</h2><ul class="method-list"><li><strong>Precio de referencia:</strong> $80.000 COP por unidad del producto analizado. No se asigna este precio automáticamente a los pads de algodón. SKU, contenido y frecuencia de recompra por confirmar.</li><li><strong>Público:</strong> personas de 18 años o más, sin límite superior, de todos los géneros y en todo el territorio colombiano. Los perfiles son contextos de uso sin restricciones por ciudades.</li><li><strong>Base demográfica:</strong> 39.721.750 adultos en Colombia en 2027, sumando edades de 18 a 100 y más de las proyecciones DANE: 19.166.107 hombres y 20.555.643 mujeres. La fuente clasifica por sexo; no mide identidad de género.</li><li><strong>Universo de comunicación:</strong> 30 M para toda Colombia, 18+ y todos los géneros. Se parte de ${short(DIGITAL_POTENTIAL)} de potencial digital, calculado con población 2027 y tasas TIC 2025 constantes por edad. Para 18–24 se usa la tasa 12–24 como aproximación. El margen hasta 30 M es una decisión de planeación; no certifica afinidad ni inventario publicitario.</li><li><strong>Referencia económica:</strong> DANE reporta 38,0% de clase media y 3,3% de clase alta en 2025. Aplicar el 41,3% a la población adulta de 2027 produce aproximadamente 16,4 M. Es una aproximación: supone la misma proporción por edad y estabilidad entre años; no es un cruce observado de edad e ingresos.</li><li><strong>Compradores:</strong> no hay una cifra validada. Tener ingresos no demuestra presupuesto disponible, interés en la categoría, acceso al producto ni disposición a pagar $80.000. Las sensibilidades de 20%, 35% y 50% son supuestos exploratorios, no pronósticos ni intervalos de confianza.</li><li><strong>Simulador:</strong> el universo es editable y corresponde solo al escenario. El alcance modelado no equivale a compradores. La base inicial es 30 M compartidos por las dos líneas para comunicación. El análisis de compra al precio informado es independiente y no constituye una reducción obligatoria de esa base.</li><li><strong>Portafolio:</strong> brief JGB pp. 21–24. Los cinco contextos amplían el enfoque inicial del brief para incluir hombres y mujeres. Empaques originales; retratos ilustrativos generados con IA.</li></ul>${marketSources()}<div class="dialog-actions"><button class="button primary" data-action="open-market">Explorar universo y precio ›</button></div>`);}
function download(name,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(rows){return '\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n');}
function guideText(){const {medium,audience,product}=guideContext,g=guides[medium];return `PADS Audience Lab · ${g.title}\nAudiencia: ${audiences.find(a=>a.id===audience).name}\nProducto: ${products.find(p=>p.id===product).name}\n${g.status}\n\n${g.steps.map((s,i)=>`${i+1}. ${s}`).join('\n\n')}\n\nTemas sugeridos (no categorías confirmadas):\n${[...audienceSignals[audience],...productSignals[product]].join('\n')}\n\n${signalText(audience,product,medium)}\n\n${g.note}\n\n${g.sources.map(([n,u])=>n+': '+u).join('\n')}`;}
function signalText(audience,product,medium){const s=signalPlan(audience,product,medium);return ['MAPA DE SEÑALES · HIPÓTESIS','Toda Colombia · 18+ sin límite superior · todos los géneros; sin filtros por ciudad.',s.moment,'Contextos: '+s.contexts.join(', '),'Producto: '+s.topics.join(', '),'Búsquedas propuestas: '+s.searches.join(' | '),'Pieza: '+s.creative,s.productMessage,'Dónde: '+s.place,'Activación: '+s.input,'Datos propios: '+s.remarketing,'Prueba: '+s.test,'Medición: '+s.metric,s.validation].join('\n\n');}
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function exportAudiences(){const normalize=t=>t.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const list=audiences.filter(a=>normalize([a.name,a.context,a.need,a.message].join(' ')).includes(normalize(query)));download('PADS_Audiencias.csv',csv([['Audiencia','Contexto','Necesidad','Mensaje propuesto','Producto','Universo nacional de comunicación','Cobertura','Edad','Género','Estado'],...list.flatMap(a=>products.filter(p=>filter==='all'||p.id===filter).map(p=>[a.name,a.context,a.need,a.message,p.name,MARKET.planningUniverse,'Toda Colombia','18+ sin límite superior','Todos los géneros','Hipótesis inclusiva; sin tamaño de grupo']))]),'text/csv;charset=utf-8');toast('Audiencias exportadas con el filtro actual.');}
function exportSim(){try{const r=simulate(simState);download('PADS_Escenario.csv',csv([['PADS · Escenario de alcance, no compradores'],['Cobertura','Toda Colombia'],['Edad','18+ sin límite superior'],['Género','Todos los géneros'],['Universo nacional recomendado',MARKET.planningUniverse],['Potencial digital · cálculo propio',DIGITAL_POTENTIAL],['Universo único del escenario',r.population.unique],['Fuente población',MARKET.populationUrl],['Fuente internet',MARKET.internetUrl],...buyerExportRows(r.population.unique,buyerState.currentShare,r.final.unique),...Object.entries(simState),['Modelo','Saturación homogénea e independencia entre líneas; 12 olas iguales'],[],['Ola','Inversión COP','Impresiones','Alcance limpieza','Alcance Control Poros','Intersección entre productos','Únicos','Frecuencia','Compradores actuales alcanzados · supuesto','Audiencia nueva alcanzada · supuesto','Intersección entre perfiles de compra'],...r.rows.map(v=>{const b=splitBuyerAudience({universe:r.population.unique,currentShare:buyerState.currentShare,reach:v.unique}),total=Math.round(v.unique),current=Math.round(total*b.current/b.universe);return[v.period,v.spend,Math.round(v.impressions),Math.round(v.cleanReach),Math.round(v.poreReach),Math.round(v.overlap),total,v.frequency.toFixed(3),current,total-current,0];})]),'text/csv;charset=utf-8');toast('Escenario y supuestos exportados.');}catch(e){toast(e.message);}}
function exportMarket(){const r=marketScenario(marketState);download('PADS_Universo_2027.csv',csv([['PADS · Universo de comunicación y escenario de compra'],['Cobertura','Toda Colombia'],['Edad','18+ sin límite superior'],['Género','Todos los géneros'],['Año de planeación',MARKET.year],['Adultos · proyección DANE',MARKET.adults],['Potencial digital · cálculo propio',DIGITAL_POTENTIAL],['Universo de comunicación recomendado',MARKET.planningUniverse],...buyerExportRows(MARKET.planningUniverse,buyerState.currentShare),['Método digital','Población 2027 × tasas TIC 2025 constantes; tasa 12–24 como proxy de 18–24'],['Clase media y alta 2025 · todas las edades',MARKET.middleHighShare],['Referencia económica · aproximación propia',ECONOMIC_PROXY],['Método económico','Proporción de todas las edades 2025 aplicada a adultos 2027; sin cruce edad-ingreso ni internet'],['Precio unitario COP',marketState.price],['Meses entre compras',marketState.months],['Presupuesto como porcentaje del ingreso',marketState.budgetShare],['Umbral aritmético de ingreso COP',r.threshold],['Afinidad-acceso-disposición conjunta supuesta (%)',marketState.qualification],['Escenario condicionado · no compradores medidos',r.qualified],['Fuentes población',MARKET.populationUrl],['Fuentes internet',MARKET.internetUrl],['Fuentes ingresos',MARKET.incomeUrl],['Validación','Requiere SKU, distribución y evidencia de disposición de compra al precio real']]),'text/csv;charset=utf-8');toast('Análisis exportado con hipótesis y fuentes.');}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const {action,value}=el.dataset;
 if(action==='buyer-method')showBuyerMethod();
 if(action==='export-buyers')exportBuyers();
 if(action==='open-market'){closeDialog();location.hash='market';}
 if(action==='apply-national'){simState={...EXAMPLE,budget:Number.isFinite(simState.budget)&&simState.budget>=0&&simState.budget<=1e12?simState.budget:EXAMPLE.budget,cpm:Number.isFinite(simState.cpm)&&simState.cpm>0?simState.cpm:EXAMPLE.cpm,cleansingShare:Number.isFinite(simState.cleansingShare)&&simState.cleansingShare>=0&&simState.cleansingShare<=100?simState.cleansingShare:EXAMPLE.cleansingShare};saveScenario();location.hash='simulator';if(currentRoute==='simulator')render();}
 if(action==='apply-market'){let r;try{r=marketScenario(marketState);}catch(error){toast(error.message);return;}const n=r.qualified;if(!n){toast('El escenario debe incluir al menos una persona.');return;}simState={...EXAMPLE,cleansingOnly:0,shared:0,poreCareOnly:n,cleansingShare:0,marketPrice:marketState.price,marketMonths:marketState.months,marketBudgetShare:marketState.budgetShare,marketQualification:marketState.qualification};saveScenario();location.hash='simulator';}
 if(action==='export-market'){try{exportMarket();}catch(error){toast(error.message);}}
 if(action==='filter'){filter=value;render();}
 if(action==='audience')audienceDetail(value);
 if(action==='product')productDetail(value);
 if(action==='guide')guideDetail(value);
 if(action==='audience-guide')guideDetail(value,el.dataset.audience);
 if(action==='method')method();
 if(action==='close')closeDialog();
 if(action==='map-audience'&&(value==='all'||audiences.some(a=>a.id===value))){mapAudience=value;render();$(`[data-action="map-audience"][data-value="${value}"]`)?.focus({preventScroll:true});}
 if(action==='product-audiences'||action==='product-media'){filter=value;closeDialog();location.hash=action==='product-audiences'?'audiences':'media';render();}
 if(action==='copy-guide'){try{await navigator.clipboard.writeText(guideText());toast('Guía copiada con sus ejemplos y fuentes.');}catch{download('PADS_Guia.txt',guideText());toast('Se descargó la guía; el navegador no permitió copiar.');}}
 if(action==='download-guide'){download('PADS_Guia_'+guideContext.medium+'.txt',guideText());toast('Guía descargada.');}
 if(action==='export-audiences')exportAudiences();
 if(action==='export-sim')exportSim();
 if(action==='reset-sim'){simState={...EXAMPLE};saveScenario();render();toast('Base nacional de 30 M restablecida.');}
});
document.addEventListener('input',e=>{if(e.target.matches('[data-buyer-share]')){changeBuyerShare(e.target);return;}if(e.target.dataset.market){marketState[e.target.dataset.market]=Number(e.target.value);$('#market-results').innerHTML=marketResults();return;}if(e.target.id==='audience-search'){query=e.target.value;$('#audience-results').innerHTML=audienceResults();}if(e.target.dataset.sim){simState[e.target.dataset.sim]=e.target.value===''?NaN:Number(e.target.value);$('#share-value').textContent=simState.cleansingShare+'% limpieza';$('#sim-results').innerHTML=simResults();refreshBuyerProjection();try{simulate(simState);const saved=saveScenario();$('#save-status').textContent=saved?'Escenario válido guardado en este navegador. Valores de planeación editables.':'Escenario válido activo en esta sesión; el navegador no permite guardarlo.';}catch{}}});
document.addEventListener('change',e=>{if(e.target.matches('[data-buyer-share]')&&e.target.getAttribute('aria-invalid')==='true'){e.target.value=buyerState.currentShare;changeBuyerShare(e.target);}if(e.target.id==='guide-audience'){guideContext.audience=e.target.value;renderGuide();$('#guide-audience').focus();}if(e.target.id==='guide-product'){guideContext.product=e.target.value;renderGuide();$('#guide-product').focus();}});
$('.skip-link').addEventListener('click',e=>{e.preventDefault();$('#content').focus();});
$('#menu-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));});
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
$('#detail-dialog').addEventListener('cancel',()=>{if(lastFocus?.isConnected)lastFocus.focus();});
window.addEventListener('hashchange',()=>{if($('#detail-dialog').open)closeDialog();render();window.scrollTo({top:0,behavior:'instant'});$('#content').focus({preventScroll:true});});
render();
